import React, { Component } from 'react'
import { Row, Col, Button, Spin, Table, notification } from 'antd'
import { connect } from 'react-redux'
import Step3Actions from '../../../../../../redux/productConfig/actions'
import { get } from 'lodash'
import Step3Wrapper from '../index'
import { Section3DataTable } from '../../../../constants/detailPageSections'
import ModalWrapper from '../../../detailPage/modalData'
import { localStorageCheck } from '../../../../util/localstorageCheck'
const {
  resetProductConfigRedux,
  productDetailPackges,
  getPackagesValidation,
  productDetailsAttributes
} = Step3Actions
class PackageListPage extends Component {
  state = {
    packagTableData: [],
    visible: false,
    selectedPackage: {},
    validationData: [],
    step1Data: {},
    step2Data: []
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const {
      productDetailPackages,
      productDetailPackagesMessage,
      getproductPackageValidationMessage,
      getproductPackageValidation,
      productDetailAttributes,
      productDetailAttributesMessage
    } = nextProps

    if (productDetailPackagesMessage === 'success') {
      this.setState({
        packagTableData: get(productDetailPackages, 'data.details', [])
      })
      this.props.resetProductConfigRedux(['productDetailPackagesMessage'])
    }
    if (productDetailPackagesMessage !== 'success' && productDetailPackagesMessage !== undefined) {
      notification.error({
        message: 'Error',
        description: 'Error in Loading Package List'
      })
      this.props.resetProductConfigRedux(['productDetailPackagesMessage'])
    }
    if (getproductPackageValidationMessage === 'success') {
      this.setState({
        validationData: get(getproductPackageValidation, 'data.details', [])
      })
    }
    if (productDetailAttributesMessage === 'success') {
      const step2Data = get(productDetailAttributes, 'data.details', [])
      this.setState({
        step2Data
      })
      window.sessionStorage.setItem('Step2', JSON.stringify(get(productDetailAttributes, 'data.details', [])))
      this.props.resetProductConfigRedux(['productDetailAttributesMessage'])
    }
  }

  async componentDidMount () {
    const { location } = this.props
    const formName = get(location, 'state.formName', '')
    switch (formName) {
      case 'Step2': {
        const formData = get(location, 'state.formData', '')
        const productAttributes = localStorageCheck(window.sessionStorage.getItem('Step2')) || []
        if (productAttributes.length === 0) {
          const productCode = get(formData, 'code', '')
          await this.props.productDetailsAttributes({ query: { productCode: productCode, type: 'creation,endorsement' } })
        }
        const code = get(formData, 'code', '')
        if (code) {
          this.setState({
            step1Data: formData
          })
          this.props.productDetailPackges({ query: { productCode: code } })
        }
      }
        break
      case 'package-info':
      case 'validation-table': {
        const step2Data = get(location, 'state.formData.step2Data', [])
        const step1Data = get(location, 'state.formData.step1Data', {})
        const productCode = get(step1Data, 'code')
        this.setState({
          step1Data,
          step2Data
        })
        this.props.productDetailPackges({ query: { productCode: productCode } })
      }
        break
      default: {
        this.props.history.push({
          pathname: '/product-config/create-product/1'
        })
      }
    }
  }

  previousPageHandler=() => {
    const { history } = this.props
    history.push({
      pathname: '/product-config/create-product/2/table'
    })
  }

  handleFinshWizardHandler=() => {
    const { history } = this.props
    history.push({
      pathname: '/product-config'
    })
    window.sessionStorage.clear()
  }

  closeModel = () => {
    this.setState({
      visible: false
    })
    window.sessionStorage.removeItem('formData')
  }

  packageModal =(val) => {
    const selectedPackage = { ...val }
    window.sessionStorage.setItem('formData', JSON.stringify(selectedPackage))
    this.setState({
      selectedPackage: { ...val },
      visible: true
    }, () => {
      // TODO: localstorage should be conditional on the basis of paage comes
      const data = this.state.step1Data
      const code = get(data, 'code', '')
      if (code) {
        const packageCode = get(val, 'code', '')
        this.props.getPackagesValidation({
          query: {
            productCode: code,
            packageCode: packageCode
          }
        })
      }
    })
  }

  handleAddPackageHandler = () => {
    const { history } = this.props
    history.push({
      pathname: '/product-config/create-product/3/package-info',
      state: {
        formName: 'package-table',
        formData: {
          step1Data: this.state.step1Data,
          step2Data: this.state.step2Data
        }
      }
    })
  }

  editPackageHandler = () => {
    const { selectedPackage } = this.state
    const packageCode = get(selectedPackage, 'code', '')
    this.props.history.push({
      pathname: `/product-config/edit-package/${packageCode}`,
      state: {
        formName: 'modal-page-edit',
        formData: {
          packageData: selectedPackage,
          step1Data: this.state.step1Data,
          step2Data: this.state.step2Data
        }
      }
    })
  }

  editDataValidationHandler = () => {
    const { selectedPackage, validationData, step2Data, step1Data } = this.state
    const packageCode = get(selectedPackage, 'code', '')
    const enableEndorsement = get(selectedPackage, 'has_endorsement_flow', false)
    const step2DataAtt = enableEndorsement ? step2Data : step2Data.filter(item => item.attribute_type === 'creation')
    this.props.history.push({
      pathname: `/product-config/edit/validation/${packageCode}`,
      state: {
        formName: 'modal-page-validation',
        formData: {
          initialData: validationData,
          step2Data: step2DataAtt,
          step1Data: step1Data
        }
      }
    })
  }

  render () {
    const { packagTableData, visible, selectedPackage, step1Data, step2Data } = this.state
    const { productDetailPackagesLoading, productDetailPackagesError } = this.props
    const productCode = get(step1Data, 'code', '')

    return (
      <Step3Wrapper>
        {/* Modal Starts Here */}
        <ModalWrapper
          visible={visible}
          detailSection={selectedPackage}
          closeModel={this.closeModel}
          // loading={productDetailPackagesLoading && !productDetailPackagesError}
          productCode={productCode}
          providerData={JSON.parse(window.sessionStorage.getItem('provider')) || []}
          editPackageInfo={this.editPackageHandler}
          section2Data={step2Data}
          editDataValidationFunction={this.editDataValidationHandler}
        />
        {/*  Modal Ends Here */}
        <Row type='flex' justify='space-between'>
          <Col span={8}>
            <h3 className='table-label'><b>Package List Data</b></h3>
          </Col>
          <Col span={8}>
            <Button type='primary' className='table-button' onClick={this.handleAddPackageHandler}>Add Package</Button>
          </Col>
        </Row>
        <Row type='flex' justify='center'>
          <Col span={18} className='table-section'>
            <Spin spinning={productDetailPackagesLoading && !productDetailPackagesError} tip='Data Loading...'>
              <Table
                bordered
                columns={Section3DataTable.call(this, {
                  ...JSON.parse(window.sessionStorage.getItem('Step2'))
                })}
                dataSource={packagTableData}
              />
            </Spin>
          </Col>
        </Row>
        <Row type='flex' justify='center'>
          {/* <Col>
            <Button onClick={this.previousPageHandler}>Previous</Button>
          </Col> */}
          <Col className='button-section'>
            <Button type='primary' disabled={packagTableData.length === 0} onClick={this.handleFinshWizardHandler}>Finish</Button>
          </Col>
        </Row>
      </Step3Wrapper>
    )
  }
}
export default connect(
  state => ({
    productDetailPackages: state.ProductConfigurable.productDetailPackges,
    productDetailPackagesMessage: state.ProductConfigurable.productDetailPackgesMessage,
    productDetailPackagesLoading: state.Loading.GET_PRODUCT_PACKGES,
    productDetailPackagesError: state.Error.GET_PRODUCT_PACKGES,
    getproductPackageValidation: state.ProductConfigurable.getproductPackageValidation,
    getproductPackageValidationMessage: state.ProductConfigurable.getproductPackageValidationMessage
  }), {
    resetProductConfigRedux,
    productDetailPackges,
    getPackagesValidation,
    productDetailsAttributes
  }
)(PackageListPage)
